// Export count
export const TOTAL_MUNICIPALITIES = INDIANA_MUNICIPALITIES.length;

// Helper function to get municipality by slug
export function getMunicipalityBySlug(slug: string): Municipality | undefined {
  return INDIANA_MUNICIPALITIES.find(m => m.slug === slug);
}

// Helper function to get municipalities by county
export function getMunicipalitiesByCounty(county: string): Municipality[] {
  return INDIANA_MUNICIPALITIES.filter(m => m.county === county);
}

// Get unique counties
export function getUniqueCounties(): string[] {
  return Array.from(new Set(INDIANA_MUNICIPALITIES.map(m => m.county))).sort();
}
